CREATE TABLE `mailmessage` (
  `mailMessageId` bigint NOT NULL AUTO_INCREMENT,
  `to` varchar(50) DEFAULT NULL,
  `subject` varchar(50) DEFAULT NULL,
  `message` text,
  `fromUser` varchar(50) DEFAULT NULL,
  `ifFailed` int NOT NULL DEFAULT '0',
  `noOfAttempt` int NOT NULL DEFAULT '0',
  `reason` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`mailMessageId`)
) ENGINE=InnoDB AUTO_INCREMENT=354 DEFAULT CHARSET=latin1;
