INSERT INTO `mailmessage` VALUES (259,'A\\²â@¯ËÜáÊ¨¬RÐŽ‘,ü·Íï','Activation Email','<!DOCTYPE html\r\n  PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\">\r\n<html xmlns=\"http://www.w3.org/1999/xhtml\">\r\n\r\n<head>\r\n<meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\r\n<title>Bloomkite - Activation Email</title>\r\n<style type=\"text/css\">\r\nbody {\r\n	margin: 0;\r\n	padding: 0;\r\n	min-width: 100% !important;\r\n}\r\n\r\nimg {\r\n	height: auto;\r\n}\r\n\r\n.content {\r\n	width: 100%;\r\n	max-width: 600px;\r\n}\r\n\r\n.header {\r\n	padding: 40px 30px 20px 30px;\r\n}\r\n\r\n.innerpadding {\r\n	padding: 10px 30px 10px 30px;\r\n}\r\n\r\n.borderbottom {\r\n	border-bottom: 1px solid #f2eeed;\r\n}\r\n\r\n.subhead {\r\n	font-size: 15px;\r\n	color: #ffffff;\r\n	font-family: sans-serif;\r\n	letter-spacing: 10px;\r\n}\r\n\r\n.h1, .h2, .bodycopy {\r\n	color: #153643;\r\n	font-family: sans-serif;\r\n}\r\n\r\n.h1 {\r\n	font-size: 33px;\r\n	line-height: 38px;\r\n	font-weight: bold;\r\n}\r\n\r\n.h2 {\r\n	padding: 0 0 10px 0;\r\n	font-size: 24px;\r\n	line-height: 28px;\r\n	font-weight: bold;\r\n}\r\n\r\n.bodycopy {\r\n	font-size: 16px;\r\n	line-height: 22px;\r\n	text-align: justify;\r\n}\r\n\r\n.button {\r\n	text-align: center;\r\n	font-size: 18px;\r\n	font-family: sans-serif;\r\n	font-weight: bold;\r\n	padding: 0 30px 0 30px;\r\n}\r\n\r\n.button a {\r\n	color: #ffffff;\r\n	text-decoration: none;\r\n}\r\n\r\n.footer {\r\n	padding: 20px 30px 15px 30px;\r\n}\r\n\r\n.footercopy {\r\n	font-family: sans-serif;\r\n	font-size: 14px;\r\n	color: #ffffff;\r\n}\r\n\r\n.footercopy a {\r\n	color: #ffffff;\r\n	text-decoration: underline;\r\n}\r\n\r\n@media only screen and (max-width: 550px) , screen and\r\n	(max-device-width: 550px) {\r\n	body[bloomkite] .hide {\r\n		display: none !important;\r\n	}\r\n	body[bloomkite] .buttonwrapper {\r\n		background-color: transparent !important;\r\n	}\r\n	body[bloomkite] .button {\r\n		padding: 0px !important;\r\n	}\r\n	body[bloomkite] .button a {\r\n		background-color: #e05443;\r\n		padding: 15px 15px 13px !important;\r\n	}\r\n	body[bloomkite] .unsubscribe {\r\n		display: block;\r\n		margin-top: 20px;\r\n		padding: 10px 50px;\r\n		background: #2f3942;\r\n		border-radius: 5px;\r\n		text-decoration: none !important;\r\n		font-weight: bold;\r\n	}\r\n}\r\n\r\n/*@media only screen and (min-device-width: 601px) {\r\n    .content {width: 600px !important;}\r\n    .col425 {width: 425px!important;}\r\n    .col380 {width: 380px!important;}\r\n    }*/\r\n</style>\r\n</head>\r\n\r\n<body bloomkite bgcolor=\"#f5fafd\">\r\n	<table width=\"100%\" bgcolor=\"#f5fafd\" border=\"0\" cellpadding=\"0\"\r\n		cellspacing=\"0\">\r\n		<tr>\r\n			<td>\r\n				<!--[if (gte mso 9)|(IE)]>\r\n      <table width=\"600\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n        <tr>\r\n          <td>\r\n    <![endif]-->\r\n				<table bgcolor=\"#ffffff\" class=\"content\" align=\"center\"\r\n					cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n					<tr>\r\n						<td bgcolor=\"#195d7f\" class=\"header\">\r\n							<!--[if (gte mso 9)|(IE)]>\r\n            <table width=\"425\" align=\"left\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\r\n              <tr>\r\n                <td>\r\n          <![endif]-->\r\n							<table class=\"col425\" align=\"left\" border=\"0\" cellpadding=\"0\"\r\n								cellspacing=\"0\" style=\"width: 100%; text-align: center;\">\r\n								<tr>\r\n									<td>\r\n										<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n											<tr>\r\n												<td class=\"subhead\" style=\"padding: 0 0 0 3px;\"><img\r\n													class=\"fix\"\r\n													src=\"http://development.bloomkite.com/images/logo.png\"\r\n													width=\"300\" height=\"70\" border=\"0\" alt=\"\" /></td>\r\n											</tr>\r\n										</table>\r\n									</td>\r\n								</tr>\r\n							</table> <!--[if (gte mso 9)|(IE)]>\r\n                </td>\r\n              </tr>\r\n          </table>\r\n          <![endif]-->\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td class=\"innerpadding borderbottom\">\r\n							<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">\r\n								<tr>\r\n									<td class=\"h2\">Welcome to Bloomkite!</td>\r\n								</tr>\r\n								<tr>\r\n									<td class=\"bodycopy\">\r\n										<table>\r\n											<tbody>\r\n												<tr>\r\n													<td>Dear jey,</td>\r\n												</tr>\r\n												<tr>\r\n													<!-- <td class=\"innerpadding\" style=\"padding-left: 0;\"> -->\r\n													<td style=\"padding-top: 10px\">Warm Greetings from\r\n														BloomKite....</td>\r\n												</tr>\r\n												<tr>\r\n													<td style=\"padding-top: 10px\">Thank you for signing up\r\n														to become an early member of <a target=\"_blank\"\r\n														href=\"http://www.bloomkite.com\">www.bloomkite.com</a>\r\n													</td>\r\n												</tr>\r\n												<tr>\r\n													<td style=\"padding-top: 10px\">We have established\r\n														BloomKite in order to create a Hybrid Financial Advisory\r\n														platform by connecting Financial Advisors and Consumers\r\n														with the best user experience.</td>\r\n												</tr>\r\n											</tbody>\r\n										</table>\r\n									</td>\r\n								</tr>\r\n							</table>\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td class=\"innerpadding bodycopy borderbottom\"\r\n							style=\"padding-top: 10px; padding-bottom: 10px;\">We are\r\n							privileged to have you on our portal. As gratitude, we are\r\n							offering you <strong>Pro+ membership</strong> to experience all\r\n							new features.\r\n						</td>\r\n					</tr>\r\n					<tr>\r\n						<td class=\"innerpadding borderbottom\">\r\n							<table width=\"115\" align=\"left\" border=\"0\" cellpadding=\"0\"\r\n								cellspacing=\"0\">\r\n				